          </div>

          <div className="form-group">
            <label>Rating (0-5)</label>
            <input
              type="number"
              step="0.1"
              min="0"
              max="5"
              value={formData.rating}
              onChange={(e) => setFormData({ ...formData, rating: e.target.value })}
            />
            {errors.rating && <div className="error">{errors.rating}</div>}
          </div>

          <div className="form-group">
            <label>Product Image</label>
            <input
