```typescript
import React, { createContext, useContext, useState, useEffect } from 'react';
import axios from 'axios';

interface CartItem {
  id: number;
  product: {
    id: number;
    name: string;
    price: number;
    image_url: string;
  };
  quantity: number;
  subtotal: number;
}

interface CartContextType {
  items: CartItem[];
  total: number;
  itemCount: number;
  loading: boolean;
  addToCart: (productId: number, quantity?: number) => Promise<void>;
  updateQuantity: (itemId: number, quantity: number) => Promise<void>;
  removeFromCart: (itemId: number) => Promise<void>;
  refreshCart: () => Promise<void>;
}

const CartContext = createContext<CartContextType | undefined>(undefined);

export const CartProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [items, setItems] = useState<CartItem[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(false);
  const [token, setToken] = useState<string | null>(localStorage.getItem('guest_token'));

  useEffect(() => {
    if (!token) {
      // Create guest session
      const guestToken = `guest_${Date.now()}_${Math.random().toString(36)}`;
      localStorage.setItem('guest_token', guestToken);
      setToken(guestToken);
    }

    // Try to load cart from localStorage for guest users
    const savedCart = localStorage.getItem('cart');
    if (savedCart) {
      try {
        const parsed = JSON.parse(savedCart);
        setItems(parsed.items || []);
        setTotal(parsed.total || 0);
      } catch (e) {
        console.error('Failed to parse saved cart');
      }
    }
  }, []);

  useEffect(() => {
    // Save cart to localStorage
    localStorage.setItem('cart', JSON.stringify({ items, total }));
  }, [items, total]);

  const refreshCart = async () => {
    // For guest users, cart is stored in localStorage
    // This is a simplified implementation
    const cartTotal = items.reduce((sum, item) => sum + item.subtotal, 0);
    setTotal(cartTotal);
  };

  const addToCart = async (productId: number, quantity: number = 1) => {
    setLoading(true);
    try {
      // Fetch product details
      const response = await axios.get(`/api/products/${productId}`);
      const product = response.data;

      // Check if item already in cart
      const existingIndex = items.findIndex(item => item.product.id === productId);

      if (existingIndex >= 0) {
        const newItems = [...items];
        newItems[existingIndex].quantity += quantity;
        newItems[existingIndex].subtotal = newItems[existingIndex].quantity * newItems[existingIndex].product.price;
        setItems(newItems);
      } else {
        const newItem: CartItem = {
          id: Date.now(),
          product: {
            id: product.id,
            name: product.name,
            price: product.price,
            image_url: product.image_url
          },
          quantity,
          subtotal: product.price * quantity
        };
        setItems([...items, newItem]);
      }

      await refreshCart();
    } catch (error) {
      console.error('Failed to add to cart', error);
      throw error;
    } finally {
      setLoading(false);
    }
  };

  const updateQuantity = async (itemId: number, quantity: number) => {
    if (quantity < 1) return;

    setLoading(true);
    try {
      const newItems = items.map(item => {
        if (item.id === itemId) {
          return {
            ...item,
            quantity,
            subtotal: item.product.price * quantity
          };
        }
        return item;
      });
      setItems(newItems);
      await refreshCart();
    } catch (error) {
      console.error('Failed to update quantity', error);
      throw error;
    } finally {
      setLoading(false);
    }
  };

  const removeFromCart = async (itemId: number) => {
    setLoading(true);
    try {
      setItems(items.filter(item => item.id !== itemId));
      await refreshCart();
    } catch (error) {
      console.error('Failed to remove from cart', error);
      throw error;
    } finally {
      setLoading(false);
    }
  };

  const itemCount = items.reduce((sum, item) => sum + item.quantity, 0);

  return (
    <CartContext.Provider value={{ items, total, itemCount, loading, addToCart, updateQuantity, removeFromCart, refreshCart }}>
      {children}
    </CartContext.Provider>
  );
};

export const useCart = () => {
  const context = useContext(CartContext);
  if (!context) {
    throw new Error('useCart must be used within CartProvider');
  }
  return context;
};
