import React, { useState, useEffect } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import axios from 'axios';

interface Product {
  id: number;
  name: string;
  description: string;
  price: number;
  category_id: number;
  rating: number;
  image_url: string;
  stock: number;
}

interface Category {
  id: number;
  name: string;
}

const ProductListing: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [loading, setLoading] = useState(true);
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();

  // Filter states
  const [selectedCategories, setSelectedCategories] = useState<number[]>([]);
  const [priceRange, setPriceRange] = useState({ min: 0, max: 1000 });
  const [minRating, setMinRating] = useState(0);
  const [sortBy, setSortBy] = useState('created_at');

  useEffect(() => {
    fetchCategories();
  }, []);

  useEffect(() => {
    fetchProducts();
  }, [selectedCategories, priceRange, minRating, sortBy, searchParams]);

  const fetchCategories = async () => {
    try {
      const response = await axios.get('/api/categories');
      setCategories(response.data.categories);
    } catch (error) {
      console.error('Failed to fetch categories', error);
    }
  };

  const fetchProducts = async () => {
    setLoading(true);
    try {
      const params: any = {
        per_page: 50,
        sort_by: sortBy,
        sort_order: 'desc'
      };

      const search = searchParams.get('search');
      if (search) params.search = search;

      if (selectedCategories.length > 0) {
        params.category_id = selectedCategories[0]; // Simplified: only first category
      }

      if (priceRange.min > 0) params.min_price = priceRange.min;
      if (priceRange.max < 1000) params.max_price = priceRange.max;
      if (minRating > 0) params.min_rating = minRating;

      const response = await axios.get('/api/products', { params });
      setProducts(response.data.products);
    } catch (error) {
      console.error('Failed to fetch products', error);
    } finally {
      setLoading(false);
    }
  };

  const handleCategoryToggle = (categoryId: number) => {
    setSelectedCategories(prev =>
      prev.includes(categoryId)
        ? prev.filter(id => id !== categoryId)
        : [...prev, categoryId]
    );
  };

  const handleProductClick = (productId: number) => {
    navigate(`/products/${productId}`);
  };

  if (loading) return <div className="loading">Loading products...</div>;

  return (
    <div className="container">
      <div className="listing-container">
        <aside className="filters">
          <div className="filter-group">
            <h3>Categories</h3>
            {categories.map(category => (
              <label key={category.id}>
                <input
                  type="checkbox"
                  checked={selectedCategories.includes(category.id)}
                  onChange={() => handleCategoryToggle(category.id)}
                />
                {category.name}
              </label>
            ))}
          </div>

          <div className="filter-group">
            <h3>Price Range</h3>
            <input
              type="range"
              min="0"
              max="1000"
              value={priceRange.max}
              onChange={(e) => setPriceRange({ ...priceRange, max: parseInt(e.target.value) })}
            />
            <div className="price-range">
              <span>${priceRange.min}</span>
              <span>${priceRange.max}</span>
            </div>
          </div>

          <div className="filter-group">
            <h3>Minimum Rating</h3>
            <select value={minRating} onChange={(e) => setMinRating(parseFloat(e.target.value))}>
              <option value="0">All Ratings</option>
              <option value="1">1+ Stars</option>
              <option value="2">2+ Stars</option>
              <option value="3">3+ Stars</option>
              <option value="4">4+ Stars</option>
            </select>
          </div>
        </aside>

        <main className="products-section">
          <div className="view-controls">
            <div>
              <strong>{products.length}</strong> products found
            </div>
            <div style={{ display: 'flex', gap: '15px', alignItems: 'center' }}>
              <select value={sortBy} onChange={(e) => setSortBy(e.target.value)}>
                <option value="created_at">Newest</option>
                <option value="price">Price</option>
                <option value="rating">Rating</option>
                <option value="name">Name</option>
              </select>
              <div className="view-toggle">
                <button
                  className={`view-btn ${viewMode === 'grid' ? 'active' : ''}`}
                  onClick={() => setViewMode('grid')}
                >
                  Grid
                </button>
                <button
                  className={`view-btn ${viewMode === 'list' ? 'active' : ''}`}
                  onClick={() => setViewMode('list')}
                >
                  List
                </button>
              </div>
            </div>
          </div>

          {viewMode === 'grid' ? (
            <div className="product-grid">
              {products.map(product => (
                <div key={product.id} className="product-card" onClick={() => handleProductClick(product.id)}>
                  {product.image_url && <img src={product.image_url} alt={product.name} />}
                  <div className="product-card-content">
                    <h3>{product.name}</h3>
                    <div className="price">${product.price.toFixed(2)}</div>
                    <div className="rating">⭐ {product.rating?.toFixed(1) || '0.0'}</div>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <div className="product-list">
              {products.map(product => (
                <div key={product.id} className="product-list-item" onClick={() => handleProductClick(product.id)}>
                  {product.image_url && <img src={product.image_url} alt={product.name} />}
                  <div className="product-list-info">
                    <h3>{product.name}</h3>
                    <p>{product.description?.substring(0, 150)}...</p>
                    <div className="price">${product.price.toFixed(2)}</div>
                    <div className="rating">⭐ {product.rating?.toFixed(1) || '0.0'}</div>
                    <div>Stock: {product.stock}</div>
                  </div>
                </div>
              ))}
            </div>
          )}

          {products.length === 0 && (
            <div style={{ textAlign: 'center', padding: '60px', color: '#666' }}>
              No products found matching your criteria.
            </div>
          )}
        </main>
      </div>
    </div>
  );
};

export default ProductListing;
```

