import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import axios from 'axios';
import { useCart } from '../context/CartContext';

interface Product {
  id: number;
  name: string;
  description: string;
  price: number;
  category_id: number;
  category_name: string;
  rating: number;
  image_url: string;
  stock: number;
}

const ProductDetail: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const [product, setProduct] = useState<Product | null>(null);
  const [recommendations, setRecommendations] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [addingToCart, setAddingToCart] = useState(false);
  const { addToCart } = useCart();

  useEffect(() => {
    if (id) {
      fetchProduct();
      fetchRecommendations();
    }
  }, [id]);

  const fetchProduct = async () => {
    try {
      const response = await axios.get(`/api/products/${id}`);
      setProduct(response.data);
    } catch (error) {
      console.error('Failed to fetch product', error);
    } finally {
      setLoading(false);
    }
  };

  const fetchRecommendations = async () => {
    try {
      // Fetch similar products from same category
      const productResponse = await axios.get(`/api/products/${id}`);
      const response = await axios.get(`/api/products?category_id=${productResponse.data.category_id}&per_page=4`);
      setRecommendations(response.data.products.filter((p: Product) => p.id !== parseInt(id!)));
    } catch (error) {
      console.error('Failed to fetch recommendations', error);
    }
  };

  const handleAddToCart = async () => {
    if (!product) return;

    setAddingToCart(true);
    try {
      await addToCart(product.id);
      alert('Product added to cart!');
    } catch (error) {
      alert('Failed to add to cart');
    } finally {
      setAddingToCart(false);
    }
  };

  if (loading) return <div className="loading">Loading product...</div>;
  if (!product) return <div className="error">Product not found</div>;

  return (
    <div className="container">
      <div className="product-detail">
        <div className="product-detail-content">
          <div className="product-images">
            {product.image_url ? (
              <img src={product.image_url} alt={product.name} className="main-image" />
            ) : (
              <div className="main-image" style={{ background: '#f0f0f0', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                No Image
              </div>
            )}
          </div>

          <div className="product-info">
            <h1>{product.name}</h1>
            <div className="rating">⭐ {product.rating?.toFixed(1) || '0.0'} / 5.0</div>
            <div className="price">${product.price.toFixed(2)}</div>
            <div className="stock">
              {product.stock > 0 ? (
                <span style={{ color: 'green' }}>✓ In Stock ({product.stock} available)</span>
              ) : (
                <span style={{ color: 'red' }}>✗ Out of Stock</span>
              )}
            </div>
            <p className="description">{product.description}</p>
            <div style={{ marginBottom: '15px', color: '#666' }}>
              Category: <strong>{product.category_name}</strong>
            </div>
            <button
              className="add-to-cart-btn"
              onClick={handleAddToCart}
              disabled={product.stock === 0 || addingToCart}
            >
              {addingToCart ? 'Adding...' : 'Add to Cart'}
            </button>
          </div>
        </div>

        {recommendations.length > 0 && (
          <div className="recommendations">
            <h2>You May Also Like</h2>
            <div className="product-grid">
              {recommendations.map(rec => (
                <div
                  key={rec.id}
                  className="product-card"
                  onClick={() => window.location.href = `/products/${rec.id}`}
                >
                  {rec.image_url && <img src={rec.image_url} alt={rec.name} />}
                  <div className="product-card-content">
                    <h3>{rec.name}</h3>
                    <div className="price">${rec.price.toFixed(2)}</div>
                    <div className="rating">⭐ {rec.rating?.toFixed(1) || '0.0'}</div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default ProductDetail;
