import React from 'react';
import { useCart } from '../context/CartContext';
import { Link } from 'react-router-dom';

const Cart: React.FC = () => {
  const { items, total, updateQuantity, removeFromCart, loading } = useCart();

  if (items.length === 0) {
    return (
      <div className="container">
        <div className="cart-page">
          <div className="empty-cart">
            <h2>Your cart is empty</h2>
            <p>Add some products to get started!</p>
            <Link to="/" className="btn btn-primary" style={{ display: 'inline-block', marginTop: '20px' }}>
              Continue Shopping
            </Link>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="container">
      <div className="cart-page">
        <h1>Shopping Cart</h1>

        <div className="cart-items">
          {items.map(item => (
            <div key={item.id} className="cart-item">
              {item.product.image_url && (
                <img src={item.product.image_url} alt={item.product.name} />
              )}

              <div className="cart-item-info">
                <h3>{item.product.name}</h3>
                <div className="price">${item.product.price.toFixed(2)}</div>
              </div>

              <div className="cart-item-quantity">
                <button
                  className="qty-btn"
                  onClick={() => updateQuantity(item.id, item.quantity - 1)}
                  disabled={loading || item.quantity <= 1}
                >
                  -
                </button>
                <span style={{ minWidth: '30px', textAlign: 'center' }}>{item.quantity}</span>
                <button
                  className="qty-btn"
                  onClick={() => updateQuantity(item.id, item.quantity + 1)}
                  disabled={loading}
                >
                  +
                </button>
              </div>

              <div style={{ fontWeight: 'bold', fontSize: '18px' }}>
                ${item.subtotal.toFixed(2)}
              </div>

              <button
                className="cart-item-remove"
                onClick={() => removeFromCart(item.id)}
                disabled={loading}
              >
                Remove
              </button>
            </div>
          ))}
        </div>

        <div className="cart-summary">
          <h2>Total: ${total.toFixed(2)}</h2>
          <button className="btn btn-primary" style={{ marginTop: '20px', padding: '15px 40px', fontSize: '16px' }}>
            Proceed to Checkout
          </button>
        </div>
      </div>
    </div>
  );
};

export default Cart;
